const body = $input.first().json.body || {};
const colabUrl = body.colabUrl || $env.COLAB_API_URL || 'http://127.0.0.1:8000';
const jobId = 'job_' + Date.now() + '_' + Math.random().toString(36).substr(2, 6);

const payload = {
  jobId: jobId,
  topic: body.topic || 'Automação de Conteúdo',
  style: body.style || 'Cyberpunk',
  voice: body.voice || 'pt-BR-FranciscaNeural',
  duration: body.duration || '15s',
  narration: body.narration || '',
  scenes: body.scenes || [],
  callbackWebhook: body.callbackWebhook || 'http://127.0.0.1:5678/webhook/media-completed'
};

return [{ json: { colabUrl, payload, jobId } }];

const prep = $('Code - Prepare Colab Payload').first().json;
let colabResp = null;

try {
  colabResp = $input.first().json;
} catch (e) {}

if (colabResp && colabResp.job_id) {
  return [{
    json: {
      success: true,
      status: 'queued',
      source: 'colab_gpu_t4',
      jobId: colabResp.job_id,
      estimatedDurationSeconds: 60,
      message: 'Renderização enviada com sucesso para a GPU T4 no Google Colab.'
    }
  }];
}

// Resilient mock/fallback response if Colab is offline during local dev
return [{
  json: {
    success: true,
    status: 'queued',
    source: 'local_queue_simulation',
    jobId: prep.jobId,
    estimatedDurationSeconds: 45,
    message: 'Job registrado na fila do StudioOps. (Colab worker em modo de espera)',
    previewPayload: prep.payload
  }
}];
